import json
import unittest
from unittest.mock import patch

from model_runtime.heavy_review import (
    _validate_review,
    review,
)


class HeavyReviewTests(unittest.TestCase):
    def test_pass_is_overridden_when_verifier_failed(self):
        model_review = {
            "verdict": "pass",
            "summary": "ok",
            "issues": [],
            "tests_to_run": [],
        }
        result = _validate_review(model_review, {"ok": False})
        self.assertEqual(result["verdict"], "corrections")
        self.assertTrue(result["issues"])

    def test_pass_kept_when_verifier_ok(self):
        model_review = {
            "verdict": "pass",
            "summary": "ok",
            "issues": [],
            "tests_to_run": [],
        }
        result = _validate_review(model_review, {"ok": True})
        self.assertEqual(result["verdict"], "pass")

    @patch("model_runtime.heavy_review._request_message")
    def test_reasoning_only_first_call_recovers(self, request_message):
        request_message.side_effect = [
            {"content": "", "reasoning_content": "lange interne Analyse"},
            {
                "content": json.dumps(
                    {
                        "verdict": "corrections",
                        "summary": "PDO-Blocker beheben",
                        "issues": [
                            {
                                "severity": "blocker",
                                "path": "inc/funktionen_benutzer.php",
                                "evidence": "duplicate placeholder",
                                "required_change": "eindeutige Placeholder",
                            }
                        ],
                        "tests_to_run": ["PHP Syntax"],
                    }
                )
            },
        ]

        result = review(
            {},
            {"ok": False, "blockers": [{"code": "X"}]},
            "diff",
            "http://example.invalid",
            "model",
            1,
        )

        self.assertEqual(result["verdict"], "corrections")
        self.assertEqual(
            result["_generated_by"],
            "heavy_model_recovered",
        )
        self.assertIn("Leerer content", result["_recovery_reason"])
        self.assertEqual(request_message.call_count, 2)


if __name__ == "__main__":
    unittest.main()
